    60→│   │   ├── instruction-set.js   # Instruction definitions (8-10 core RISC)
    61→│   │   └── pipeline.js          # Pipeline stage logic
    62→│   ├── animation/
    63→│   │   ├── animation-engine.js  # Frame-based animation controller
    64→│   │   ├── sequence-loader.js   # Pre-scripted program sequences
    65→│   │   └── timing-controller.js # Playback speed management
    66→│   └── programs/
