    71→
    72→**Key principle:** Separate concerns - CPU simulation logic, animation control, and UI are independent modules.
    73→
    74→### Pattern 1: Immutable State Snapshot Architecture
    75→
    76→**What:** Each animation frame is a complete, immutable snapshot of CPU state
    77→**When to use:** For all state transitions in the animation system
    78→
    79→**Example:**
    80→```javascript
    81→// Source: Modern state snapshot pattern (2026)
    82→// Influenced by: https://github.com/kevinnayar/temporis
    83→// https://macwright.com/2015/05/18/practical-undo
    84→
    85→class CPUState {
    86→  constructor() {
    87→    // Pipeline stage registers (IF/ID, ID/EX, EX/MEM, MEM/WB)
    88→    this.pipeline = {
    89→      IF: { instruction: 0, pc: 0 },
    90→      ID: { instruction: 0, opcode: 0, rs: 0, rt: 0, rd: 0, imm: 0 },
    91→      EX: { aluResult: 0, writeData: 0, writeReg: 0 },
    92→      MEM: { memData: 0, writeData: 0, writeReg: 0 },
    93→      WB: { writeData: 0, writeReg: 0 }
    94→    };
    95→
    96→    // Register file (32 registers, 32-bit each)
    97→    this.registers = new Uint32Array(32);
    98→
    99→    // Data memory (256 words = 1KB for demo)
   100→    this.memory = new Uint32Array(256);
   101→
   102→    // Control state
   103→    this.pc = 0;              // Program counter
   104→    this.cycleCount = 0;      // Total cycles executed
   105→    this.instructionCount = 0; // Instructions completed
   106→
   107→    // Metadata for visualization
   108→    this.changedRegisters = new Set(); // Track which regs changed this cycle
   109→    this.hazards = [];        // Active hazards this cycle
   110→  }
   111→
   112→  // Create immutable clone for next frame
   113→  clone() {
   114→    const cloned = structuredClone(this);
   115→    Object.freeze(cloned);
   116→    Object.freeze(cloned.pipeline);
   117→    Object.freeze(cloned.pipeline.IF);
   118→    Object.freeze(cloned.pipeline.ID);
   119→    Object.freeze(cloned.pipeline.EX);
   120→    Object.freeze(cloned.pipeline.MEM);
   121→    Object.freeze(cloned.pipeline.WB);
   122→    return cloned;
   123→  }
   124→}
   125→```
   126→
   127→**Why this pattern:**
   128→- Immutability prevents accidental state corruption during animation
   129→- Enables instant jump to any frame (no need to replay from start)
   130→- Supports bidirectional stepping without complex undo logic
   131→- Object.freeze() adds zero runtime cost in production, catches bugs in dev
   132→
   133→### Pattern 2: Frame-Based Animation Controller
   134→
   135→**What:** Pre-generate all animation frames, store in array, navigate by index
   136→**When to use:** For all pre-scripted animation sequences
   137→
   138→**Example:**
   139→```javascript
   140→// Source: Custom implementation based on requestAnimationFrame patterns
   141→// MDN: https://developer.mozilla.org/en-US/docs/Web/API/Web_Animations_API/Using_the_Web_Animations_API
   142→// javascript.info: https://javascript.info/js-animation
   143→
   144→class AnimationEngine {
   145→  constructor() {
   146→    this.frames = [];           // Array of CPUState snapshots
   147→    this.currentFrame = 0;      // Current frame index
   148→    this.isPlaying = false;     // Playback state
   149→    this.speed = 1.0;          // Playback speed multiplier (0.1 to 5.0)
   150→    this.fps = 30;             // Target frames per second
   151→    this.lastFrameTime = 0;    // For delta-time calculation
   152→    this.rafId = null;         // requestAnimationFrame ID
   153→  }
   154→
   155→  // Load pre-scripted sequence
   156→  loadSequence(programSequence) {
   157→    this.frames = programSequence.frames; // Pre-generated array
   158→    this.currentFrame = 0;
   159→    this.isPlaying = false;
   160→    this.dispatchFrameChange();
   161→  }
   162→
   163→  // Step forward one frame
   164→  stepForward() {
   165→    if (this.currentFrame < this.frames.length - 1) {
   166→      this.currentFrame++;
   167→      this.dispatchFrameChange();
   168→    }
   169→  }
   170→
   171→  // Step backward one frame
   172→  stepBackward() {
   173→    if (this.currentFrame > 0) {
   174→      this.currentFrame--;
   175→      this.dispatchFrameChange();
   176→    }
   177→  }
   178→
   179→  // Jump to specific frame
   180→  jumpToFrame(frameIndex) {
   181→    if (frameIndex >= 0 && frameIndex < this.frames.length) {
   182→      this.currentFrame = frameIndex;
   183→      this.dispatchFrameChange();
   184→    }
   185→  }
   186→
   187→  // Play/pause animation
   188→  play() {
   189→    if (this.isPlaying) return;
   190→    this.isPlaying = true;
   191→    this.lastFrameTime = performance.now();
   192→    this.animate();
   193→  }
   194→
   195→  pause() {
   196→    this.isPlaying = false;
   197→    if (this.rafId) {
   198→      cancelAnimationFrame(this.rafId);
   199→      this.rafId = null;
   200→    }
   201→  }
   202→
   203→  // Reset to beginning
   204→  reset() {
   205→    this.pause();
   206→    this.currentFrame = 0;
   207→    this.dispatchFrameChange();
   208→  }
   209→
   210→  // Animation loop (private)
   211→  animate = (currentTime = performance.now()) => {
   212→    if (!this.isPlaying) return;
   213→
   214→    const deltaTime = currentTime - this.lastFrameTime;
   215→    const frameInterval = (1000 / this.fps) / this.speed; // Adjust for speed
   216→
   217→    if (deltaTime >= frameInterval) {
   218→      this.stepForward();
   219→      this.lastFrameTime = currentTime - (deltaTime % frameInterval);
   220→
   221→      // Stop at end
   222→      if (this.currentFrame >= this.frames.length - 1) {
   223→        this.pause();
   224→        return;
   225→      }
   226→    }
   227→
   228→    this.rafId = requestAnimationFrame(this.animate);
   229→  }
   230→
   231→  // Notify UI of frame change
   232→  dispatchFrameChange() {
   233→    window.dispatchEvent(new CustomEvent('cpu:framechange', {
   234→      detail: {
   235→        frame: this.currentFrame,
   236→        state: this.frames[this.currentFrame],
   237→        totalFrames: this.frames.length
   238→      }
   239→    }));
   240→  }
   241→
   242→  // Adjust playback speed (0.1x to 5x)
   243→  setSpeed(speedMultiplier) {
   244→    this.speed = Math.max(0.1, Math.min(5.0, speedMultiplier));
   245→  }
   246→}
   247→```
   248→
   249→**Why this pattern:**
   250→- requestAnimationFrame automatically syncs with 60fps display refresh
   251→- Delta-time calculation makes animation framerate-independent
   252→- Pre-generated frames enable instant navigation (no recalculation)
   253→- Speed multiplier controls walkthrough pace (slow learning vs fast demo)
   254→
   255→### Pattern 3: Pre-Scripted Sequence Generation
   256→
   257→**What:** Generate complete animation sequence from instruction list at load time
   258→**When to use:** For all pre-defined programs (basic instructions, Fibonacci, hazard examples)
   259→
   260→**Example:**
   261→```javascript
   262→// Source: CPU simulator pattern from educational tools
   263→// Similar to: https://yomotherboard.com/interactive-cpu-architecture-simulator/
   264→
   265→class SequenceGenerator {
   266→  // Generate animation frames from instruction array
   267→  static generateSequence(instructions, initialState = new CPUState()) {
   268→    const frames = [];
   269→    let state = initialState.clone();
   270→
   271→    // Frame 0: Initial state
   272→    frames.push(state);
   273→
   274→    // Simulate instruction-by-instruction
   275→    for (let i = 0; i < instructions.length; i++) {
   276→      const instruction = instructions[i];
   277→
   278→      // Generate frames for this instruction's pipeline journey
   279→      // Each instruction creates multiple frames as it moves through stages
   280→      const instructionFrames = this.simulateInstruction(state, instruction);
   281→
   282→      instructionFrames.forEach(frameState => {
   283→        state = frameState;
   284→        frames.push(state.clone());
   285→      });
   286→    }
   287→
   288→    return { frames, instructions };
   289→  }
   290→
   291→  // Simulate single instruction through pipeline
   292→  static simulateInstruction(currentState, instruction) {
   293→    const frames = [];
   294→
   295→    // Cycle 1: Instruction fetch (IF stage)
   296→    let state = currentState.clone();
   297→    state.pipeline.IF.instruction = instruction.encoding;
   298→    state.pipeline.IF.pc = currentState.pc;
   299→    state.cycleCount++;
   300→    frames.push(state);
   301→
   302→    // Cycle 2: Instruction decode (ID stage)
   303→    state = state.clone();
   304→    state.pipeline.ID.instruction = instruction.encoding;
   305→    state.pipeline.ID.opcode = instruction.opcode;
   306→    state.pipeline.ID.rs = instruction.rs;
   307→    state.pipeline.ID.rt = instruction.rt;
   308→    state.pipeline.ID.rd = instruction.rd;
   309→    state.pipeline.ID.imm = instruction.immediate || 0;
   310→    state.cycleCount++;
   311→    frames.push(state);
   312→
   313→    // Cycle 3: Execute (EX stage)
   314→    state = state.clone();
   315→    state.pipeline.EX = this.executeInstruction(instruction, state);
   316→    state.cycleCount++;
   317→    frames.push(state);
   318→
   319→    // Cycle 4: Memory access (MEM stage)
   320→    state = state.clone();
   321→    state.pipeline.MEM = this.memoryAccess(instruction, state);
   322→    state.cycleCount++;
   323→    frames.push(state);
   324→
   325→    // Cycle 5: Write back (WB stage)
   326→    state = state.clone();
   327→    state = this.writeBack(instruction, state);
   328→    state.instructionCount++;
   329→    state.pc += 4; // Advance PC
   330→    frames.push(state);
   331→
   332→    return frames;
   333→  }
   334→
   335→  // Execute instruction in EX stage (simplified)
   336→  static executeInstruction(instruction, state) {
   337→    const rs_val = state.registers[instruction.rs];
   338→    const rt_val = state.registers[instruction.rt];
   339→    let result = 0;
   340→
   341→    switch (instruction.opcode) {
   342→      case 'ADD':  result = rs_val + rt_val; break;
   343→      case 'SUB':  result = rs_val - rt_val; break;
   344→      case 'ADDI': result = rs_val + instruction.immediate; break;
   345→      // ... other instructions
   346→    }
   347→
   348→    return {
   349→      aluResult: result,
   350→      writeData: result,
   351→      writeReg: instruction.rd
   352→    };
   353→  }
   354→
   355→  // Memory access stage
   356→  static memoryAccess(instruction, state) {
   357→    let memData = 0;
   358→
   359→    if (instruction.opcode === 'LW') {
   360→      const address = state.pipeline.EX.aluResult;
   361→      memData = state.memory[address >> 2]; // Word-aligned
   362→    } else if (instruction.opcode === 'SW') {
   363→      const address = state.pipeline.EX.aluResult;
   364→      state.memory[address >> 2] = state.registers[instruction.rt];
   365→    }
   366→
   367→    return {
   368→      memData: memData,
   369→      writeData: state.pipeline.EX.writeData,
   370→      writeReg: state.pipeline.EX.writeReg
   371→    };
   372→  }
   373→
   374→  // Write back stage
   375→  static writeBack(instruction, state) {
   376→    const newState = state.clone();
   377→    const writeReg = state.pipeline.MEM.writeReg;
   378→
   379→    if (writeReg !== 0) { // Register 0 is hardwired to 0
   380→      const oldVal = newState.registers[writeReg];
   381→      newState.registers[writeReg] = state.pipeline.MEM.writeData;
   382→
   383→      // Track changed register for visualization
   384→      if (oldVal !== newState.registers[writeReg]) {
   385→        newState.changedRegisters.add(writeReg);
   386→      }
   387→    }
   388→
   389→    return newState;
   390→  }
   391→}
   392→
   393→// Example: Basic instruction sequence
   394→const BASIC_PROGRAM = {
   395→  name: "Basic Instructions Walkthrough",
   396→  description: "Demonstrates 8 core RISC instructions",
   397→  instructions: [
   398→    { opcode: 'ADDI', rs: 0, rt: 0, rd: 8, immediate: 10 },  // $8 = 10
   399→    { opcode: 'ADDI', rs: 0, rt: 0, rd: 9, immediate: 20 },  // $9 = 20
   400→    { opcode: 'ADD',  rs: 8, rt: 9, rd: 10, immediate: 0 },  // $10 = $8 + $9
   401→    { opcode: 'SUB',  rs: 9, rt: 8, rd: 11, immediate: 0 },  // $11 = $9 - $8
   402→    { opcode: 'SW',   rs: 8, rt: 10, immediate: 0 },         // mem[0] = $10
   403→    { opcode: 'LW',   rs: 0, rt: 0, rd: 12, immediate: 0 },  // $12 = mem[0]
   404→    { opcode: 'BEQ',  rs: 8, rt: 8, immediate: 8 },          // if $8==$8, skip 2
   405→    { opcode: 'J',    immediate: 0 }                          // jump to start
   406→  ]
   407→};
   408→```
   409→
   410→**Why this pattern:**
   411→- Pre-generation means zero computation during playback (instant navigation)
   412→- Each frame is self-contained (no dependencies on previous state)
   413→- Easy to add new instruction types (extend `executeInstruction()` switch)
   414→- Matches educational simulator pattern (step-through execution trace)
   415→
   416→### Pattern 4: RISC Instruction Encoding
   417→
   418→**What:** Represent instructions as structured objects with standard RISC fields
   419→**When to use:** For all instruction definitions in pre-scripted programs
   420→
   421→**Example:**
   422→```javascript
   423→// Source: RISC-V instruction format patterns
   424→// https://pages.hmc.edu/harris/ddca/ddcarv/DDCArv_AppB_Harris.pdf
   425→// https://danielmangum.com/posts/risc-v-bytes-intro-instruction-formats/
   426→
   427→class InstructionSet {
   428→  // R-type: Register-register operations (add, sub, and, or)
   429→  static R_TYPE = {
   430→    ADD:  { opcode: 0b0110011, funct3: 0b000, funct7: 0b0000000 },
   431→    SUB:  { opcode: 0b0110011, funct3: 0b000, funct7: 0b0100000 },
   432→    AND:  { opcode: 0b0110011, funct3: 0b111, funct7: 0b0000000 },
   433→    OR:   { opcode: 0b0110011, funct3: 0b110, funct7: 0b0000000 }
   434→  };
   435→
   436→  // I-type: Immediate operations (addi, lw)
   437→  static I_TYPE = {
   438→    ADDI: { opcode: 0b0010011, funct3: 0b000 },
   439→    LW:   { opcode: 0b0000011, funct3: 0b010 }
   440→  };
   441→
   442→  // S-type: Store operations (sw)
   443→  static S_TYPE = {
   444→    SW:   { opcode: 0b0100011, funct3: 0b010 }
   445→  };
   446→
   447→  // B-type: Branch operations (beq)
   448→  static B_TYPE = {
   449→    BEQ:  { opcode: 0b1100011, funct3: 0b000 }
   450→  };
   451→
   452→  // J-type: Jump operations (j)
   453→  static J_TYPE = {
   454→    J:    { opcode: 0b1101111 }
   455→  };
   456→
   457→  // Encode instruction to 32-bit value
   458→  static encode(type, fields) {
   459→    let encoding = 0;
   460→
   461→    switch (type) {
   462→      case 'R':
   463→        encoding = (fields.funct7 << 25) | (fields.rs2 << 20) |
   464→                   (fields.rs1 << 15) | (fields.funct3 << 12) |
   465→                   (fields.rd << 7) | fields.opcode;
   466→        break;
   467→      case 'I':
   468→        encoding = (fields.immediate << 20) | (fields.rs1 << 15) |
   469→                   (fields.funct3 << 12) | (fields.rd << 7) | fields.opcode;
   470→        break;
   471→      case 'S':
   472→        const imm_s = (fields.immediate >> 5) << 25 | (fields.immediate & 0x1F) << 7;
   473→        encoding = imm_s | (fields.rs2 << 20) | (fields.rs1 << 15) |
   474→                   (fields.funct3 << 12) | fields.opcode;
   475→        break;
   476→      // ... B-type, J-type similar
   477→    }
   478→
   479→    return encoding >>> 0; // Unsigned 32-bit
   480→  }
   481→
   482→  // Decode 32-bit instruction
   483→  static decode(instruction) {
   484→    const opcode = instruction & 0x7F;
   485→    const rd = (instruction >> 7) & 0x1F;
   486→    const funct3 = (instruction >> 12) & 0x7;
   487→    const rs1 = (instruction >> 15) & 0x1F;
   488→    const rs2 = (instruction >> 20) & 0x1F;
   489→    const funct7 = (instruction >> 25) & 0x7F;
   490→
   491→    // Determine instruction type from opcode
   492→    // Return structured instruction object
   493→    return {
   494→      opcode, rd, funct3, rs1, rs2, funct7,
   495→      type: this.getInstructionType(opcode),
   496→      mnemonic: this.getMnemonic(opcode, funct3, funct7)
   497→    };
   498→  }
   499→}
   500→```
   501→
   502→**Why this pattern:**
   503→- Matches real RISC instruction encoding (educational authenticity)
   504→- Fixed field positions simplify decode logic (matches hardware)
   505→- Binary representation enables realistic instruction visualization
   506→- Extensible to additional instructions without structural changes
   507→
   508→### Anti-Patterns to Avoid
   509→
   510→- **Mutating state objects:** Never modify state in-place. Always clone first. Mutations break bidirectional stepping and cause subtle bugs.
   511→- **Recalculating frames on demand:** Pre-generate all frames at sequence load. On-demand calculation makes backward stepping slow and complicates undo logic.
   512→- **Using setInterval for animation:** Always use requestAnimationFrame. setInterval doesn't sync with repaints, causes jank and wasted CPU cycles.
   513→- **Deep cloning with JSON.parse/stringify:** Use structuredClone(). JSON method is 3-5x slower and fails on TypedArrays, circular references, and undefined values.
   514→- **Coupling animation state to UI:** Keep animation engine independent. Use CustomEvents to notify UI. Tight coupling makes testing impossible and refactoring fragile.
   515→
   516→## Don't Hand-Roll
   517→
   518→| Problem | Don't Build | Use Instead | Why |
   519→|---------|-------------|-------------|-----|
   520→| Deep cloning objects | Custom recursive clone | `structuredClone()` | Native API handles circular refs, TypedArrays, Date, RegExp, Map, Set. Custom solutions miss edge cases and are 10x slower. |
   521→| Animation timing | Custom delta-time tracking | `requestAnimationFrame` + `performance.now()` | Browser optimizes rAF for 60fps sync, auto-pauses in background tabs, handles monitor refresh rates. Custom timing causes jank. |
   522→| State immutability | Custom immutability library (Immer, Immutable.js) | `Object.freeze()` + `structuredClone()` | Zero bundle cost, V8-optimized, sufficient for CPU state (~100KB objects). Libraries add 50KB+ for marginal benefits. |
   523→| Event system | Custom observer pattern | CustomEvent + addEventListener | Native DOM events provide debugging tools, bubbling/capture, automatic cleanup. Custom events are invisible to DevTools. |
   524→
   525→**Key insight:** Browser APIs matured significantly by 2026. Native solutions (structuredClone, requestAnimationFrame, TypedArray) are faster, smaller, and better debugged than custom implementations. Don't hand-roll what the platform provides.
   526→
   527→## Common Pitfalls
   528→
   529→### Pitfall 1: Memory Bloat from Excessive Frames
   530→
   531→**What goes wrong:** Storing 1000+ animation frames creates multi-megabyte memory footprint, slowing page load and causing mobile browser crashes.
   532→
   533→**Why it happens:** Each CPU state contains pipeline registers (5 stages × 5 fields = 25 values), 32 registers (32 × 4 bytes = 128 bytes), 256-word memory (1KB), plus metadata. A single frame is ~2KB. A 1000-frame sequence is 2MB of state snapshots.
   534→
   535→**How to avoid:**
   536→- Limit pre-scripted programs to 50-100 instructions maximum (generates ~500 frames at 5 frames/instruction)
   537→- Use TypedArray for registers/memory (50% size reduction vs regular arrays)
   538→- Clear old sequence frames when loading new program (`frames = null` to allow GC)
   539→- Consider frame decimation for long sequences (store every Nth frame, interpolate between)
   540→
   541→**Warning signs:**
   542→- Page load time >3 seconds
   543→- Memory usage >50MB in DevTools Performance monitor
   544→- Mobile browsers crashing or hanging
   545→
   546→### Pitfall 2: requestAnimationFrame Throttling in Background Tabs
   547→
   548→**What goes wrong:** User switches tabs mid-animation, returns to find animation paused or frozen even though "playing" state is true.
   549→
   550→**Why it happens:** Browsers throttle requestAnimationFrame to 1fps or pause entirely when tab is not visible. Animation loop continues calling rAF but frames advance very slowly or not at all, desynchronizing animation state from UI state.
   551→
   552→**How to avoid:**
   553→```javascript
   554→// Use Page Visibility API to detect tab switches
   555→document.addEventListener('visibilitychange', () => {
   556→  if (document.hidden && animationEngine.isPlaying) {
   557→    animationEngine.pause();
   558→    // Store state to resume later
   559→    sessionStorage.setItem('cpu-animation-paused-by-tab-switch', 'true');
   560→  } else if (!document.hidden &&
   561→             sessionStorage.getItem('cpu-animation-paused-by-tab-switch')) {
   562→    sessionStorage.removeItem('cpu-animation-paused-by-tab-switch');
   563→    animationEngine.play(); // Resume playback
   564→  }
   565→});
   566→```
   567→
   568→**Warning signs:**
   569→- Animation appears to stutter when switching back to tab
   570→- Play/pause button state mismatches actual playback
   571→- Frame counter advances very slowly in background
   572→
   573→### Pitfall 3: Race Conditions from Asynchronous Frame Loading
   574→
   575→**What goes wrong:** User clicks "load program" twice rapidly. First program's frames finish loading after second program starts loading, overwriting state and causing frame mismatches.
   576→
   577→**Why it happens:** Frame generation is CPU-intensive (100+ frames × structuredClone = 50-100ms). If not properly serialized, multiple sequence loads can interleave, causing the animation engine to reference frames from the wrong program.
   578→
   579→**How to avoid:**
   580→```javascript
   581→class AnimationEngine {
   582→  constructor() {
   583→    this.loadingPromise = null; // Track active load operation
   584→  }
   585→
   586→  async loadSequence(program) {
   587→    // Wait for previous load to complete
   588→    if (this.loadingPromise) {
   589→      await this.loadingPromise;
   590→    }
   591→
   592→    // Create new promise for this load
   593→    this.loadingPromise = (async () => {
   594→      this.pause(); // Stop current animation
   595→
   596→      // Generate frames in chunks to avoid blocking UI
   597→      const frames = await this.generateFramesAsync(program);
   598→
   599→      this.frames = frames;
   600→      this.currentFrame = 0;
   601→      this.dispatchFrameChange();
   602→
   603→      this.loadingPromise = null; // Clear when done
   604→    })();
   605→
   606→    return this.loadingPromise;
   607→  }
   608→
   609→  // Generate frames in 50-frame chunks with yielding
   610→  async generateFramesAsync(program) {
   611→    const frames = [];
   612→    const CHUNK_SIZE = 50;
   613→
   614→    for (let i = 0; i < program.instructions.length; i += CHUNK_SIZE) {
   615→      const chunk = program.instructions.slice(i, i + CHUNK_SIZE);
   616→      const chunkFrames = SequenceGenerator.generateChunkFrames(chunk);
   617→      frames.push(...chunkFrames);
   618→
   619→      // Yield to UI every 50 instructions
   620→      await new Promise(resolve => setTimeout(resolve, 0));
   621→    }
   622→
   623→    return frames;
   624→  }
   625→}
   626→```
