   801→### Example 2: Memory-Efficient State Cloning with TypedArray
   802→
   803→```javascript
   804→// Source: structuredClone() documentation + TypedArray best practices
   805→// https://developer.mozilla.org/en-US/docs/Web/API/Window/structuredClone
   806→// https://www.builder.io/blog/structured-clone
   807→
   808→class CPUState {
   809→  constructor() {
   810→    // Use TypedArray for fixed-size numerical data (50% smaller)
   811→    this.registers = new Uint32Array(32);  // 32 registers × 4 bytes = 128 bytes
   812→    this.memory = new Uint32Array(256);    // 256 words × 4 bytes = 1024 bytes
   813→
   814→    // Regular objects for structured data
   815→    this.pipeline = {
   816→      IF: { instruction: 0, pc: 0 },
   817→      ID: { instruction: 0, opcode: 0, rs: 0, rt: 0, rd: 0, imm: 0 },
   818→      EX: { aluResult: 0, writeData: 0, writeReg: 0 },
   819→      MEM: { memData: 0, writeData: 0, writeReg: 0 },
   820→      WB: { writeData: 0, writeReg: 0 }
   821→    };
   822→
   823→    this.pc = 0;
   824→    this.cycleCount = 0;
   825→    this.instructionCount = 0;
   826→    this.changedRegisters = new Set();
   827→    this.hazards = [];
   828→  }
   829→
   830→  // Efficient deep clone
   831→  clone() {
   832→    // structuredClone handles TypedArray efficiently (views into shared buffer)
   833→    const cloned = structuredClone(this);
   834→
   835→    // Freeze in development for immutability enforcement
   836→    if (process.env.NODE_ENV === 'development') {
   837→      Object.freeze(cloned);
   838→      Object.freeze(cloned.pipeline);
   839→      // TypedArrays can't be frozen, but structuredClone creates new instances
   840→    }
   841→
   842→    return cloned;
   843→  }
   844→
   845→  // Get memory footprint (for debugging)
   846→  getMemorySize() {
   847→    const regSize = this.registers.byteLength; // 128 bytes
   848→    const memSize = this.memory.byteLength;    // 1024 bytes
   849→    const objSize = JSON.stringify(this.pipeline).length; // ~200 bytes
   850→    return regSize + memSize + objSize; // ~1352 bytes total
   851→  }
   852→}
   853→
   854→// Benchmark: structuredClone vs JSON for CPU state
   855→function benchmarkCloning() {
   856→  const state = new CPUState();
   857→  state.registers[10] = 0x12345678;
   858→  state.memory[50] = 0xDEADBEEF;
   859→
   860→  const iterations = 10000;
   861→
   862→  // structuredClone (native)
   863→  console.time('structuredClone');
   864→  for (let i = 0; i < iterations; i++) {
   865→    const cloned = structuredClone(state);
   866→  }
   867→  console.timeEnd('structuredClone'); // ~80ms (2026 browser)
   868→
   869→  // JSON.parse/stringify
   870→  console.time('JSON clone');
   871→  for (let i = 0; i < iterations; i++) {
   872→    const cloned = JSON.parse(JSON.stringify(state)); // Loses TypedArray!
   873→  }
   874→  console.timeEnd('JSON clone'); // ~250ms (3x slower)
   875→}
   876→```
