   878→### Example 3: Performance-Optimized Frame Generation
   879→
   880→```javascript
   881→// Source: Web Workers pattern for CPU-intensive tasks
   882→// https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API
   883→
   884→// Main thread: Offload frame generation to avoid blocking UI
   885→class SequenceLoader {
   886→  static async generateSequenceAsync(program) {
   887→    // Option 1: Use Web Worker for long sequences (100+ instructions)
   888→    if (program.instructions.length > 100) {
   889→      return this.generateInWorker(program);
   890→    }
   891→
   892→    // Option 2: Use chunked generation with yielding for shorter sequences
   893→    return this.generateWithYielding(program);
   894→  }
   895→
   896→  // Chunked generation (yields to UI every 50 instructions)
   897→  static async generateWithYielding(program) {
   898→    const frames = [];
   899→    let state = new CPUState();
   900→
   901→    const CHUNK_SIZE = 50;
   902→    for (let i = 0; i < program.instructions.length; i += CHUNK_SIZE) {
   903→      const chunkEnd = Math.min(i + CHUNK_SIZE, program.instructions.length);
   904→
   905→      // Generate frames for chunk
   906→      for (let j = i; j < chunkEnd; j++) {
   907→        const instruction = program.instructions[j];
   908→        const instructionFrames = SequenceGenerator.simulateInstruction(
   909→          state,
   910→          instruction
   911→        );
   912→        frames.push(...instructionFrames);
   913→        state = instructionFrames[instructionFrames.length - 1];
   914→      }
   915→
   916→      // Yield to browser to update UI / handle events
   917→      await new Promise(resolve => setTimeout(resolve, 0));
   918→
   919→      // Update progress
   920→      const progress = ((chunkEnd / program.instructions.length) * 100).toFixed(0);
   921→      updateLoadingProgress(progress);
   922→    }
   923→
   924→    return { frames, instructions: program.instructions };
   925→  }
   926→
   927→  // Web Worker generation (for very long sequences)
   928→  static generateInWorker(program) {
   929→    return new Promise((resolve, reject) => {
   930→      const worker = new Worker('sequence-generator-worker.js');
   931→
   932→      worker.postMessage({ program });
   933→
   934→      worker.onmessage = (event) => {
   935→        const { frames, instructions } = event.data;
   936→        worker.terminate();
   937→        resolve({ frames, instructions });
   938→      };
   939→
   940→      worker.onerror = (error) => {
   941→        worker.terminate();
   942→        reject(error);
   943→      };
   944→    });
   945→  }
   946→}
   947→
   948→// sequence-generator-worker.js (separate file)
   949→self.onmessage = (event) => {
   950→  const { program } = event.data;
   951→
   952→  // Generate frames in worker thread (no UI blocking)
   953→  const sequence = SequenceGenerator.generateSequence(
   954→    program.instructions,
   955→    new CPUState()
   956→  );
   957→
   958→  // Send back to main thread
   959→  self.postMessage(sequence);
   960→};
   961→```
